<?php session_start(); require_once __DIR__.'/../Model/AppData.php'; $items=AppData::foundItems(); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Found Items</title><link rel="stylesheet" href="style.css"></head><body><?php include 'header.php'; ?><main class="page"><div class="page-top"><h1 class="section-title">Found Items</h1><a class="btn btn-primary" href="submit.php">＋ &nbsp;Report Found Item</a></div><div class="search"><input placeholder="Search found items..."><span>⌕</span></div><div class="item-grid"><?php foreach($items as $item): ?><article><div class="item-img">400 × 300</div><div class="item-name-row"><span class="item-name"><?php echo htmlspecialchars($item['name']); ?></span><span class="date"><?php echo $item['date']; ?></span></div><div class="item-location"><?php echo htmlspecialchars($item['location']); ?></div><div class="item-description"><?php echo htmlspecialchars($item['description']); ?></div><span class="status <?php echo $item['status']==='Pending'?'yellow':'green'; ?>"><?php echo $item['status']; ?></span><a class="item-action claim-action" href="claim.php?id=<?php echo $item['id']; ?>">Claim Item</a></article><?php endforeach; ?></div></main></body></html>
